#!/bin/bash
# generated by run_group.py
set -o pipefail
__regress_fails=0
trap '__rc=$?; echo "[regress] command failed (rc=$__rc): $BASH_COMMAND" >&2; __regress_fails=$((__regress_fails + 1))' ERR
export TT_METAL_PROFILER_DIR=$TMPDIR/dit_profiler   # the job's own /tmp: the device logs stay off /data
python $REGRESS_HARNESS_DIR/dit_ring_joint_perf.py --q q256 --k k512

exit $(( __regress_fails > 0 ? 1 : 0 ))
